router6.post("/bank-accounts/:accountId/transactions", async (req, res) => {
  try {
    const accountId = parseInt(req.params.accountId);
    const { clientId, transactionDate, description, debit, credit } = req.body;
    const data = {
      clientId: parseInt(clientId),
      bankAccountId: accountId,
      transactionDate: new Date(transactionDate),
      description,
      debit: debit || "0.00",
      credit: credit || "0.00",
      isReconciled: false
    };
    const [result] = await db.insert(bankTransactions).values(data);
    const [account] = await db.select().from(bankAccounts).where(eq6(bankAccounts.id, accountId));
    if (account) {
      const current = parseFloat(account.currentBalance || "0");
      const d = parseFloat(data.debit);
      const c = parseFloat(data.credit);
      const newBalance = current + d - c;
      await db.update(bankAccounts).set({ currentBalance: newBalance.toFixed(2) }).where(eq6(bankAccounts.id, accountId));
      await db.update(bankTransactions).set({ balance: newBalance.toFixed(2) }).where(eq6(bankTransactions.id, result.insertId));
    }
    res.json({ id: result.insertId, ...data });
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: "Failed to post bank transaction" });
  }
});
