router6.post("/reconciliation/match", async (req, res) => {
  try {
    const { transactionId, matchedToType, matchedToId, clientId } = req.body;
    await db.update(bankTransactions).set({ isReconciled: true, matchedToType, matchedToId: parseInt(matchedToId) }).where(eq6(bankTransactions.id, parseInt(transactionId)));
    if (matchedToType === "Invoice") {
      await db.update(salesInvoices).set({ status: "Paid" }).where(eq6(salesInvoices.id, parseInt(matchedToId)));
    } else if (matchedToType === "Purchase") {
      await db.update(purchases).set({ status: "Paid" }).where(eq6(purchases.id, parseInt(matchedToId)));
    }
    res.json({ success: true, message: "Matched successfully" });
  } catch (error) {
    res.status(500).json({ message: "Failed to match transaction" });
  }
});
