router6.post("/vat-period", async (req, res) => {
  try {
    const { clientId, description, fromDate, toDate, vatStatus, lateClaimsIncluded } = req.body;
    if (!clientId || !fromDate || !toDate) {
      return res.status(400).json({ message: "clientId, fromDate and toDate are required" });
    }
    const cId = parseInt(clientId);
    const from = new Date(fromDate);
    const to = new Date(toDate);
    const salesCondition = lateClaimsIncluded ? and5(
      eq6(salesInvoices.clientId, cId),
      lte2(salesInvoices.invoiceDate, to),
      inArray4(salesInvoices.status, ["Unpaid", "PartiallyPaid", "Paid"])
    ) : and5(
      eq6(salesInvoices.clientId, cId),
      gte2(salesInvoices.invoiceDate, from),
      lte2(salesInvoices.invoiceDate, to),
      inArray4(salesInvoices.status, ["Unpaid", "PartiallyPaid", "Paid"])
    );
    const sales = await db.select().from(salesInvoices).where(salesCondition);
    const billsCondition = lateClaimsIncluded ? and5(
      eq6(purchases.clientId, cId),
      lte2(purchases.billDate, to),
      inArray4(purchases.status, ["Unpaid", "PartiallyPaid", "Paid"])
    ) : and5(
      eq6(purchases.clientId, cId),
      gte2(purchases.billDate, from),
      lte2(purchases.billDate, to),
      inArray4(purchases.status, ["Unpaid", "PartiallyPaid", "Paid"])
    );
    const bills = await db.select().from(purchases).where(billsCondition);
    const salesCn = await db.select().from(creditNotes).where(
      and5(
        eq6(creditNotes.clientId, cId),
        eq6(creditNotes.type, "Sales"),
        gte2(creditNotes.creditNoteDate, from),
        lte2(creditNotes.creditNoteDate, to)
      )
    );
    const purchaseCn = await db.select().from(creditNotes).where(
      and5(
        eq6(creditNotes.clientId, cId),
        eq6(creditNotes.type, "Purchase"),
        gte2(creditNotes.creditNoteDate, from),
        lte2(creditNotes.creditNoteDate, to)
      )
    );
    let grossBox1 = 0;
    let grossBox6 = 0;
    sales.forEach((s) => {
      grossBox1 += parseFloat(s.vatTotal || "0");
      grossBox6 += parseFloat(s.subTotal || "0");
    });
    let salesCnVat = 0;
    let salesCnNet = 0;
    salesCn.forEach((cn) => {
      salesCnVat += parseFloat(cn.vatTotal || "0");
      salesCnNet += parseFloat(cn.subTotal || "0");
    });
    let grossBox4 = 0;
    let grossBox7 = 0;
    bills.forEach((b) => {
      grossBox4 += parseFloat(b.vatTotal || "0");
      grossBox7 += parseFloat(b.subTotal || "0");
    });
    let purCnVat = 0;
    let purCnNet = 0;
    purchaseCn.forEach((cn) => {
      purCnVat += parseFloat(cn.vatTotal || "0");
      purCnNet += parseFloat(cn.subTotal || "0");
    });
    const box1 = Math.max(0, grossBox1 - salesCnVat);
    const box2 = 0;
    const box3 = box1 + box2;
    const box4 = Math.max(0, grossBox4 - purCnVat);
    const box5 = box3 - box4;
    const box6 = Math.max(0, grossBox6 - salesCnNet);
    const box7 = Math.max(0, grossBox7 - purCnNet);
    const box8 = 0;
    const box9 = 0;
    const [r] = await db.insert(vatPeriods).values({
      clientId: cId,
      description: description || `VAT Return ${fromDate} to ${toDate}`,
      fromDate: from,
      toDate: to,
      vatDueOnSales: box1.toFixed(2),
      vatReclaimedOnPurchases: box4.toFixed(2),
      netVatDue: box5.toFixed(2),
      box1VatDueSales: box1.toFixed(2),
      box2VatDueAcquisitions: box2.toFixed(2),
      box3TotalVatDue: box3.toFixed(2),
      box4VatReclaimed: box4.toFixed(2),
      box5NetVat: box5.toFixed(2),
      box6TotalSalesExVat: box6.toFixed(2),
      box7TotalPurchasesExVat: box7.toFixed(2),
      box8TotalEuSupplies: box8.toFixed(2),
      box9TotalEuAcquisitions: box9.toFixed(2),
      lateClaimsIncluded: !!lateClaimsIncluded,
      vatStatus: vatStatus || "Calculated",
      paymentStatus: "Unpaid"
    });
    res.json({
      id: r.insertId,
      clientId: cId,
      description: description || `VAT Return ${fromDate} to ${toDate}`,
      fromDate,
      toDate,
      box1: box1.toFixed(2),
      box2: box2.toFixed(2),
      box3: box3.toFixed(2),
      box4: box4.toFixed(2),
      box5: box5.toFixed(2),
      box6: box6.toFixed(2),
      box7: box7.toFixed(2),
      box8: box8.toFixed(2),
      box9: box9.toFixed(2),
      isRefund: box4 > box3
    });
  } catch (e) {
    res.status(500).json({ message: "Failed to create VAT period", error: e.message });
  }
});
