router6.post("/receipts/:id/deallocate", async (req, res) => {
  try {
    const invoiceId = parseInt(req.params.id);
    const { amount } = req.body;
    const [invoice] = await db.select().from(salesInvoices).where(eq6(salesInvoices.id, invoiceId));
    if (!invoice) {
      return res.status(404).json({ message: "Invoice not found" });
    }
    const currentPaid = parseFloat(invoice.paidAmount || "0");
    const reverseAmount = amount ? Math.min(currentPaid, parseFloat(amount)) : currentPaid;
    const newPaid = Math.max(0, currentPaid - reverseAmount);
    const grandTotal = parseFloat(invoice.grandTotal || "0");
    let newStatus = "Unpaid";
    if (newPaid >= grandTotal && grandTotal > 0) {
      newStatus = "Paid";
    } else if (newPaid > 0) {
      newStatus = "PartiallyPaid";
    }
    await db.update(salesInvoices).set({
      paidAmount: newPaid.toFixed(2),
      status: newStatus
    }).where(eq6(salesInvoices.id, invoiceId));
    res.json({
      success: true,
      invoiceId,
      reversedAmount: reverseAmount.toFixed(2),
      remainingPaid: newPaid.toFixed(2),
      newStatus,
      message: `Deallocated \xA3${reverseAmount.toFixed(2)} from invoice ${invoice.invoiceNumber}. Status is now ${newStatus}.`
    });
  } catch (error) {
    res.status(500).json({ message: "Failed to deallocate receipt", error: error.message });
  }
});
