router7.post("/pensions/assess/:clientId", async (req, res) => {
  try {
    const clientId = parseInt(req.params.clientId);
    const [scheme] = await db.select().from(payeSchemes).where(eq7(payeSchemes.clientId, clientId));
    if (!scheme) return res.status(404).json({ message: "PAYE scheme not found" });
    const empList = await db.select().from(employees).where(eq7(employees.payeSchemeId, scheme.id));
    const now = (/* @__PURE__ */ new Date()).toISOString().split("T")[0];
    let assessedCount = 0;
    for (const emp of empList) {
      if (emp.status !== "Active") continue;
      const annualGross = parseFloat(emp.grossRate || "0") * (emp.salaryType === "AnnualSalary" ? 1 : 12);
      const workerCategory = annualGross >= 1e4 ? "Eligible Jobholder" : annualGross >= 6240 ? "Non-eligible Worker" : "Entitled Worker";
      const actionTaken = workerCategory === "Eligible Jobholder" ? "Enrolled" : "Not Enrolled";
      await db.insert(payrollPensionAssessments).values({
        clientId,
        employeeId: emp.id,
        assessmentDate: now,
        workerCategory,
        actionTaken
      });
      assessedCount++;
    }
    res.json({ message: `Successfully assessed ${assessedCount} employees for Auto Enrolment.` });
  } catch (e) {
    res.status(500).json({ message: "Failed to run pension assessment" });
  }
});
