    await db.delete(apStatutoryNotes).where(eq14(apStatutoryNotes.periodId, periodId));
    await db.delete(apReportOptions).where(eq14(apReportOptions.periodId, periodId));
    await db.delete(apCompanyOfficers).where(eq14(apCompanyOfficers.periodId, periodId));
    const tbs = await db.select().from(trialBalances).where(eq14(trialBalances.periodId, periodId));
