corporationTaxRouter.post("/:clientId/returns/:id/validate", async (req, res) => {
  try {
    const returnId = parseInt(req.params.id);
    const clientId = parseInt(req.params.clientId);
    const [ret] = await db.select().from(ct600Returns).where(eq15(ct600Returns.id, returnId));
    if (!ret) return res.status(404).json({ error: "Return not found." });
    const [client] = await db.select().from(clients).where(eq15(clients.id, clientId));
    let utr = ret.utrNumber || "";
    if (req.body.utrNumber) {
      utr = String(req.body.utrNumber).trim().replace(/\D/g, "");
      await db.update(ct600Returns).set({ utrNumber: utr }).where(eq15(ct600Returns.id, returnId));
      if (client) {
        await db.update(clients).set({ utrNumber: utr }).where(eq15(clients.id, clientId));
      }
    } else if (!utr && client?.utrNumber) {
      utr = client.utrNumber.trim().replace(/\D/g, "");
      await db.update(ct600Returns).set({ utrNumber: utr }).where(eq15(ct600Returns.id, returnId));
    }
    const errors = [];
    if (!utr || utr.length !== 10) {
      errors.push("Valid 10-digit Corporation Tax UTR is required for HMRC submission (Unique Taxpayer Reference).");
    }
    if (!ret.accountingPeriodStart || !ret.accountingPeriodEnd) {
      errors.push("Accounting period start and end dates are required.");
    }
    const isValid = errors.length === 0;
    const irMark = isValid ? `IR-${crypto3.randomBytes(12).toString("hex").toUpperCase()}` : null;
    await db.update(ct600Returns).set({
      irMark: isValid ? irMark : null,
      status: isValid ? "Validated" : "Draft",
      updatedAt: /* @__PURE__ */ new Date()
    }).where(eq15(ct600Returns.id, returnId));
    res.json({
      isValid,
      errors,
      irMark,
      utrNumber: utr,
      message: isValid ? "CT600 passed pre-filing HMRC validation." : "Validation issues detected. Please correct the highlighted errors."
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});
