corporationTaxRouter.get("/:clientId/ap-bridge/:periodId", async (req, res) => {
  try {
    const clientId = parseInt(req.params.clientId);
    const periodId = parseInt(req.params.periodId);
    const [period] = await db.select().from(accountingPeriods).where(eq15(accountingPeriods.id, periodId));
    if (!period) return res.status(404).json({ error: "Accounting period not found." });
    const [tb] = await db.select().from(trialBalances).where(and14(eq15(trialBalances.clientId, clientId), eq15(trialBalances.periodId, periodId))).limit(1);
    let turnover = 0;
    let costOfSales = 0;
    let adminExpenses = 0;
    let otherIncome = 0;
    let interestPaid = 0;
    let depreciation = 0;
    if (tb) {
      const lines = await db.select().from(trialBalanceLines).where(eq15(trialBalanceLines.trialBalanceId, tb.id));
      lines.forEach((l) => {
        const code = parseInt(l.nominalCode || "0");
        const debit = parseFloat(l.debit || "0");
        const credit = parseFloat(l.credit || "0");
        const netCredit = credit - debit;
        const netDebit = debit - credit;
        const nameLower = (l.accountName || "").toLowerCase();
        if (code >= 2300 && code <= 2399 || code >= 5200 && code <= 5399 || code === 5220 || nameLower.includes("bank") || nameLower.includes("cash in hand")) {
        } else if (code === 3900 || code === 4202 || code >= 7e3 && code <= 7099 || nameLower.includes("share capital")) {
        } else if (code >= 4e3 && code <= 4999 || code >= 1e3 && code <= 1099 || nameLower.includes("turnover") || nameLower.includes("sales")) {
          turnover += netCredit;
        } else if (code >= 1100 && code <= 1999 || code >= 5e3 && code <= 5199 || nameLower.includes("cost of sales") || nameLower.includes("purchase")) {
          costOfSales += netDebit;
        } else if (code >= 6e3 && code <= 8999 || code >= 2e3 && code <= 3999 && !nameLower.includes("capital")) {
          adminExpenses += netDebit;
          if (nameLower.includes("depreciation") || code >= 8e3 && code <= 8099) {
            depreciation += netDebit;
          }
        } else if (code >= 9e3 && code <= 9099) otherIncome += netCredit;
        else if (code >= 9100 && code <= 9199) interestPaid += netDebit;
      });
    }
    const grossProfit = turnover - costOfSales;
    const netProfit = grossProfit - adminExpenses + otherIncome - interestPaid;
    const [ixbrl] = await db.select().from(apIxbrlSubmissions).where(and14(eq15(apIxbrlSubmissions.clientId, clientId), eq15(apIxbrlSubmissions.periodId, periodId))).orderBy(desc13(apIxbrlSubmissions.createdAt)).limit(1);
    res.json({
      period,
      turnover: turnover > 0 ? turnover.toFixed(2) : "0.00",
      netAccountingProfit: netProfit.toFixed(2),
      depreciationAddBack: depreciation > 0 ? depreciation.toFixed(2) : "0.00",
      hasTrialBalance: !!tb,
      hasIxbrlAccounts: !!ixbrl,
      ixbrlSubmissionId: ixbrl?.id || null,
      message: "Figures successfully retrieved from Accounts Production Trial Balance."
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});
