systemAdminRouter.post("/settings/redis", async (req, res) => {
  try {
    const adminId = req.systemAdmin?.id;
    if (!adminId) return res.status(401).json({ message: "Unauthorized" });
    const { type, provider, url } = req.body;
    if (type === "external" && url) {
      try {
        const IORedis2 = (await import("ioredis")).default;
        const testClient = new IORedis2(url, { maxRetriesPerRequest: 1, connectTimeout: 3e3, lazyConnect: true });
        await testClient.connect();
        const ping = await testClient.ping();
        await testClient.quit();
        if (ping !== "PONG") throw new Error("Invalid response from Redis");
      } catch (err) {
        return res.status(400).json({ message: "Connection test failed", error: err.message });
      }
    }
    const payload = JSON.stringify({ type, provider, url });
    const existing = await db.select().from(systemSettings).where(eq25(systemSettings.key, "redis_config")).limit(1);
    if (existing.length > 0) {
      await db.update(systemSettings).set({ value: payload, updatedBy: adminId }).where(eq25(systemSettings.id, existing[0].id));
    } else {
      await db.insert(systemSettings).values({ key: "redis_config", value: payload, updatedBy: adminId });
    }
    const { configureRedis: configureRedis2 } = await Promise.resolve().then(() => (init_redis(), redis_exports));
    await configureRedis2(type === "external" ? url : null);
    res.json({ success: true });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});
