router27.post("/client/:clientId", async (req, res) => {
  try {
    const practiceId = req.user.practiceId;
    const clientId = parseInt(req.params.clientId);
    const { serviceId, agreedFee, billingFrequency, billingType, assignedManagerId, assignedStaffId, startDate, notes } = req.body;
    const existing = await db.select().from(pmClientServices).where(and20(eq30(pmClientServices.clientId, clientId), eq30(pmClientServices.serviceId, serviceId))).limit(1);
    if (existing.length > 0) {
      await db.update(pmClientServices).set({
        agreedFee: String(agreedFee || "0.00"),
        billingFrequency: billingFrequency || "Monthly",
        billingType: billingType || "Fixed",
        assignedManagerId: assignedManagerId || null,
        assignedStaffId: assignedStaffId || null,
        startDate: startDate ? new Date(startDate) : void 0,
        status: "Active",
        notes: notes || ""
      }).where(eq30(pmClientServices.id, existing[0].id));
      return res.json({ message: "Service assignment updated successfully", id: existing[0].id });
    }
    const [insertRes] = await db.insert(pmClientServices).values({
      practiceId,
      clientId,
      serviceId,
      agreedFee: String(agreedFee || "0.00"),
      billingFrequency: billingFrequency || "Monthly",
      billingType: billingType || "Fixed",
      assignedManagerId: assignedManagerId || null,
      assignedStaffId: assignedStaffId || null,
      startDate: startDate ? new Date(startDate) : /* @__PURE__ */ new Date(),
      status: "Active",
      notes: notes || ""
    });
    res.json({ message: "Service assigned to client successfully", id: insertRes.insertId });
  } catch (error) {
    console.error("Failed to assign service:", error);
    res.status(500).json({ message: error.message || "Failed to assign service" });
  }
});
router27.delete("/client-service/:id", async (req, res) => {
  try {
    const practiceId = req.user.practiceId;
    const id = parseInt(req.params.id);
    await db.delete(pmClientServices).where(and20(eq30(pmClientServices.id, id), eq30(pmClientServices.practiceId, practiceId)));
    res.json({ success: true, message: "Assigned service removed" });
  } catch (error) {
    res.status(500).json({ message: error.message || "Failed to remove assigned service" });
  }
});
