router28.get("/invoice-doc-templates/:id/download-zip", async (req, res) => {
  try {
    const practiceId = req.user?.practiceId || 1;
    let practiceName = "Practice";
    try {
      const [rows] = await pool.query("SELECT practice_name FROM practices WHERE id = ?", [practiceId]);
      if (rows && rows[0]?.practice_name) {
        practiceName = rows[0].practice_name;
      }
    } catch (_) {
    }
    const safeName = practiceName.replace(/[^a-zA-Z0-9_-]/g, " ").trim().replace(/\s+/g, " ");
    const zipFilename = `InvoiceTemplates_${safeName}.zip`;
    res.setHeader("Content-Type", "application/zip");
    res.setHeader("Content-Disposition", `attachment; filename="${zipFilename}"`);
    const archive = new ZipArchive({ zlib: { level: 9 } });
    archive.on("error", (err) => {
      if (!res.headersSent) res.status(500).send({ error: err.message });
    });
    archive.pipe(res);
    const masterDir = fs6.existsSync(path6.resolve(process.cwd(), "server", "templates", "sansuite-docs")) ? path6.resolve(process.cwd(), "server", "templates", "sansuite-docs") : path6.resolve(process.cwd(), "server", "templates", "capium-docs");
    const files = ["Invoice.docx", "CreditNote.docx", "Dividend.docx", "Quotation.docx"];
    for (const f of files) {
      const filePath = path6.join(masterDir, f);
      if (fs6.existsSync(filePath)) {
        archive.file(filePath, { name: f });
      }
    }
    await archive.finalize();
  } catch (error) {
    if (!res.headersSent) {
      res.status(500).json({ message: "Failed to download zip", error: error.message });
    }
  }
});
