async function getPracticeSenderInfo(practiceId, userId, reqUser) {
  let firmName = "";
  let senderEmail = "";
  try {
    const [firm] = await db.select().from(firmDetails).where(eq31(firmDetails.practiceId, practiceId)).limit(1);
    if (firm?.firmName) firmName = firm.firmName;
    if (firm?.email) senderEmail = firm.email;
    if (userId) {
      const [u] = await db.select().from(users).where(eq31(users.id, userId)).limit(1);
      if (u?.email) senderEmail = u.email;
    } else if (reqUser?.email) {
      senderEmail = reqUser.email;
    }
  } catch (err) {
    console.warn("[getPracticeSenderInfo] Error resolving practice sender info:", err);
  }
  return { firmName, senderEmail };
}
