function createRateLimiter(options) {
  const windowMs = options.windowMs || 15 * 60 * 1e3;
  const windowSec = Math.ceil(windowMs / 1e3);
  const max = options.max || 100;
  const message = options.message || "Too many requests, please try again later.";
  const keyMode = options.key || "path+ip";
  return async (req, res, next) => {
    const ip = extractIp(req);
    const banStatus = await isIpBanned(ip);
    if (banStatus.banned) {
      const msg = banStatus.permanent ? "Your IP address has been permanently banned due to repeated abuse." : `Your IP address is temporarily banned. Try again after ${banStatus.until?.toUTCString() || "some time"}.`;
      return res.status(403).json({ message: msg, banned: true, permanent: banStatus.permanent });
    }
    const rateKey = keyMode === "ip" ? `rl:${ip}` : `rl:${req.path.replace(/\//g, ":")}:${ip}`;
    try {
      const count3 = await redis.incr(rateKey);
      if (count3 === 1) {
        await redis.expire(rateKey, windowSec);
      }
      const ttl = await redis.ttl(rateKey);
      res.setHeader("X-RateLimit-Limit", max);
      res.setHeader("X-RateLimit-Remaining", Math.max(0, max - count3));
      res.setHeader("X-RateLimit-Reset", Math.ceil(Date.now() / 1e3) + (ttl > 0 ? ttl : windowSec));
      if (count3 > max) {
        const abuseKey = `rl:abuse:${ip}`;
        const abuseCount = await redis.incr(abuseKey);
        await redis.expire(abuseKey, 24 * 60 * 60);
        if (abuseCount >= VIOLATIONS_TO_BAN) {
          await recordBan(ip, `Exceeded rate limit ${abuseCount} times`);
          await redis.del(abuseKey);
          return res.status(403).json({
            message: "Your IP has been banned due to repeated rate limit violations.",
            banned: true
          });
        }
        const retryAfter = ttl > 0 ? ttl : windowSec;
        return res.status(429).json({ message, retryAfter });
      }
      next();
    } catch (err) {
      console.error("[RateLimiter] Redis error, allowing request:", err);
      next();
    }
  };
}
